/**
 * Minimal software 2D canvas.
 *
 * jsdom has no canvas and the sandbox has no GPU, so the procedural textures in
 * `src/` (fabric weave, painted face) cannot be generated by a real browser API
 * during tests or offline renders. This class implements just enough of
 * CanvasRenderingContext2D for those textures: solid and gradient fills, rects,
 * polygons with quadratics/beziers/arcs/ellipses, and thick strokes.
 *
 * It is a tool for verification, not part of the game bundle.
 */

const parseColor = (css) => {
  if (typeof css !== "string") return [0, 0, 0, 0];
  const s = css.trim();
  if (s[0] === "#") {
    let hex = s.slice(1);
    if (hex.length === 3) hex = hex.split("").map((c) => c + c).join("");
    const n = parseInt(hex.slice(0, 6), 16);
    const a = hex.length === 8 ? parseInt(hex.slice(6, 8), 16) / 255 : 1;
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255, a];
  }
  const m = s.match(/rgba?\(([^)]+)\)/);
  if (m) {
    const p = m[1].split(",").map((v) => parseFloat(v));
    return [p[0], p[1], p[2], p.length > 3 ? p[3] : 1];
  }
  if (s === "white") return [255, 255, 255, 1];
  if (s === "black") return [0, 0, 0, 1];
  return [128, 128, 128, 1];
};

class Gradient {
  constructor(kind, coords) {
    this.kind = kind;
    this.coords = coords;
    this.stops = [];
  }
  addColorStop(offset, color) {
    this.stops.push([offset, parseColor(color)]);
    this.stops.sort((a, b) => a[0] - b[0]);
  }
  at(x, y, w, h) {
    if (!this.stops.length) return [0, 0, 0, 0];
    let t;
    if (this.kind === "linear") {
      const [x0, y0, x1, y1] = this.coords;
      const dx = x1 - x0 || 1e-6;
      const dy = y1 - y0 || 1e-6;
      t = ((x - x0) * dx + (y - y0) * dy) / (dx * dx + dy * dy);
    } else {
      const [cx, cy, r0, r1] = this.coords;
      const r = this.coords.length === 6 ? this.coords[2] : r0;
      const outer = this.coords.length === 6 ? this.coords[5] : r1;
      const inner = this.coords.length === 6 ? this.coords[2] : r0;
      const d = Math.hypot(x - cx, y - cy);
      t = (d - inner) / (outer - inner || 1e-6);
      void r;
    }
    t = Math.min(1, Math.max(0, t));
    let a = this.stops[0];
    let b = this.stops[this.stops.length - 1];
    for (let i = 0; i < this.stops.length - 1; i++) {
      if (t >= this.stops[i][0] && t <= this.stops[i + 1][0]) {
        a = this.stops[i];
        b = this.stops[i + 1];
        break;
      }
    }
    const span = b[0] - a[0] || 1e-6;
    const k = Math.min(1, Math.max(0, (t - a[0]) / span));
    void w;
    void h;
    return [
      a[1][0] + (b[1][0] - a[1][0]) * k,
      a[1][1] + (b[1][1] - a[1][1]) * k,
      a[1][2] + (b[1][2] - a[1][2]) * k,
      a[1][3] + (b[1][3] - a[1][3]) * k,
    ];
  }
}

export class SoftCanvas {
  constructor(width = 300, height = 150) {
    this.width = width;
    this.height = height;
    this.data = new Uint8ClampedArray(width * height * 4);
    this._ctx = null;
  }

  getContext(kind) {
    if (kind !== "2d") return null;
    if (!this._ctx) this._ctx = new SoftContext(this);
    return this._ctx;
  }

  // three.js only reads .width/.height when uploading; no-ops kept for safety
  addEventListener() {}
  removeEventListener() {}
  toDataURL() {
    return "data:image/png;base64,";
  }
}

class SoftContext {
  constructor(canvas) {
    this.canvas = canvas;
    this.w = canvas.width;
    this.h = canvas.height;
    this.fillStyle = "#000";
    this.strokeStyle = "#000";
    this.lineWidth = 1;
    this.lineCap = "butt";
    this.globalAlpha = 1;
    this.font = "10px sans-serif";
    this.path = [];
    this.stack = [];
  }

  save() {
    this.stack.push({
      fillStyle: this.fillStyle,
      strokeStyle: this.strokeStyle,
      lineWidth: this.lineWidth,
      globalAlpha: this.globalAlpha,
    });
  }

  restore() {
    const s = this.stack.pop();
    if (s) Object.assign(this, s);
  }

  /* transforms are not needed by the generators; accepted for API parity */
  translate() {}
  rotate() {}
  scale() {}

  createLinearGradient(x0, y0, x1, y1) {
    return new Gradient("linear", [x0, y0, x1, y1]);
  }

  createRadialGradient(x0, y0, r0, x1, y1, r1) {
    // concentric approximation is enough for the soft shading used here
    return new Gradient("radial", [x1, y1, r0, r1]);
  }

  createPattern() {
    return null;
  }

  beginPath() {
    this.path = [];
  }

  closePath() {
    if (this.path.length) this.path.push(this.path[0].slice());
  }

  moveTo(x, y) {
    this.path.push([x, y]);
  }

  lineTo(x, y) {
    this.path.push([x, y]);
  }

  quadraticCurveTo(cx, cy, x, y) {
    const last = this.path[this.path.length - 1] ?? [cx, cy];
    const [x0, y0] = last;
    for (let i = 1; i <= 16; i++) {
      const t = i / 16;
      const mt = 1 - t;
      this.path.push([
        mt * mt * x0 + 2 * mt * t * cx + t * t * x,
        mt * mt * y0 + 2 * mt * t * cy + t * t * y,
      ]);
    }
  }

  bezierCurveTo(c1x, c1y, c2x, c2y, x, y) {
    const last = this.path[this.path.length - 1] ?? [c1x, c1y];
    const [x0, y0] = last;
    for (let i = 1; i <= 20; i++) {
      const t = i / 20;
      const mt = 1 - t;
      this.path.push([
        mt ** 3 * x0 + 3 * mt * mt * t * c1x + 3 * mt * t * t * c2x + t ** 3 * x,
        mt ** 3 * y0 + 3 * mt * mt * t * c1y + 3 * mt * t * t * c2y + t ** 3 * y,
      ]);
    }
  }

  arc(cx, cy, r, a0 = 0, a1 = Math.PI * 2) {
    const steps = Math.max(8, Math.ceil((Math.abs(a1 - a0) / (Math.PI * 2)) * 32));
    for (let i = 0; i <= steps; i++) {
      const a = a0 + ((a1 - a0) * i) / steps;
      this.path.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r]);
    }
  }

  ellipse(cx, cy, rx, ry, rot = 0, a0 = 0, a1 = Math.PI * 2) {
    const steps = 32;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    for (let i = 0; i <= steps; i++) {
      const a = a0 + ((a1 - a0) * i) / steps;
      const x = Math.cos(a) * rx;
      const y = Math.sin(a) * ry;
      this.path.push([cx + x * cos - y * sin, cy + x * sin + y * cos]);
    }
  }

  fillRect(x, y, w, h) {
    const x0 = Math.max(0, Math.floor(x));
    const y0 = Math.max(0, Math.floor(y));
    const x1 = Math.min(this.w, Math.ceil(x + w));
    const y1 = Math.min(this.h, Math.ceil(y + h));
    const grad = this.fillStyle instanceof Gradient ? this.fillStyle : null;
    const solid = grad ? null : parseColor(this.fillStyle);
    for (let py = y0; py < y1; py++) {
      for (let px = x0; px < x1; px++) {
        const c = grad ? grad.at(px, py) : solid;
        this.blend(px, py, c);
      }
    }
  }

  clearRect(x, y, w, h) {
    const saved = this.fillStyle;
    this.fillStyle = "rgba(0,0,0,0)";
    const x0 = Math.max(0, Math.floor(x));
    const y0 = Math.max(0, Math.floor(y));
    const x1 = Math.min(this.w, Math.ceil(x + w));
    const y1 = Math.min(this.h, Math.ceil(y + h));
    for (let py = y0; py < y1; py++) {
      for (let px = x0; px < x1; px++) {
        const i = (py * this.w + px) * 4;
        this.canvas.data[i] = 0;
        this.canvas.data[i + 1] = 0;
        this.canvas.data[i + 2] = 0;
        this.canvas.data[i + 3] = 0;
      }
    }
    this.fillStyle = saved;
  }

  fill() {
    if (this.path.length < 3) return;
    const ys = this.path.map((p) => p[1]);
    const y0 = Math.max(0, Math.floor(Math.min(...ys)));
    const y1 = Math.min(this.h - 1, Math.ceil(Math.max(...ys)));
    const grad = this.fillStyle instanceof Gradient ? this.fillStyle : null;
    const solid = grad ? null : parseColor(this.fillStyle);
    for (let y = y0; y <= y1; y++) {
      const xs = [];
      for (let i = 0; i < this.path.length; i++) {
        const a = this.path[i];
        const b = this.path[(i + 1) % this.path.length];
        const cond = a[1] <= y && b[1] > y ? 1 : b[1] <= y && a[1] > y ? -1 : 0;
        if (!cond) continue;
        xs.push(a[0] + ((y - a[1]) / (b[1] - a[1])) * (b[0] - a[0]));
      }
      xs.sort((p, q) => p - q);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        const xa = Math.max(0, Math.ceil(xs[k]));
        const xb = Math.min(this.w - 1, Math.floor(xs[k + 1]));
        for (let x = xa; x <= xb; x++) {
          this.blend(x, y, grad ? grad.at(x, y) : solid);
        }
      }
    }
  }

  stroke() {
    if (this.path.length < 2) return;
    const c = parseColor(this.strokeStyle);
    const r = Math.max(1, this.lineWidth / 2);
    for (let i = 0; i < this.path.length - 1; i++) {
      const [x0, y0] = this.path[i];
      const [x1, y1] = this.path[i + 1];
      const steps = Math.max(1, Math.ceil(Math.hypot(x1 - x0, y1 - y0)));
      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const cx = x0 + (x1 - x0) * t;
        const cy = y0 + (y1 - y0) * t;
        this.disc(cx, cy, r, c);
      }
    }
  }

  disc(cx, cy, r, color) {
    const x0 = Math.max(0, Math.floor(cx - r));
    const x1 = Math.min(this.w - 1, Math.ceil(cx + r));
    const y0 = Math.max(0, Math.floor(cy - r));
    const y1 = Math.min(this.h - 1, Math.ceil(cy + r));
    for (let y = y0; y <= y1; y++) {
      for (let x = x0; x <= x1; x++) {
        if ((x - cx) ** 2 + (y - cy) ** 2 <= r * r) this.blend(x, y, color);
      }
    }
  }

  blend(x, y, color) {
    if (!color || x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    const a = Math.min(1, color[3] * this.globalAlpha);
    if (a <= 0) return;
    const i = (y * this.w + x) * 4;
    const d = this.canvas.data;
    d[i] = color[0] * a + d[i] * (1 - a);
    d[i + 1] = color[1] * a + d[i + 1] * (1 - a);
    d[i + 2] = color[2] * a + d[i + 2] * (1 - a);
    d[i + 3] = Math.max(d[i + 3], a * 255);
  }

  /* unused by the generators, but part of the API surface */
  fillText() {}
  strokeText() {}
  drawImage() {}
  putImageData() {}
  getImageData(x, y, w, h) {
    const out = new Uint8ClampedArray(w * h * 4);
    for (let py = 0; py < h; py++) {
      for (let px = 0; px < w; px++) {
        const si = ((y + py) * this.w + (x + px)) * 4;
        const di = (py * w + px) * 4;
        out[di] = this.canvas.data[si];
        out[di + 1] = this.canvas.data[si + 1];
        out[di + 2] = this.canvas.data[si + 2];
        out[di + 3] = this.canvas.data[si + 3];
      }
    }
    return { data: out, width: w, height: h };
  }
  measureText(t) {
    return { width: (t?.length ?? 0) * 6 };
  }
}

/** Installs the software canvas into a jsdom window. */
export function installSoftCanvas(dom) {
  const proto = dom.window.HTMLCanvasElement.prototype;
  const sizes = new WeakMap();
  const realWidth = Object.getOwnPropertyDescriptor(proto, "width");
  void realWidth;
  Object.defineProperty(proto, "getContext", {
    value: function (kind) {
      if (kind !== "2d") return null;
      if (!this._soft) {
        this._soft = new SoftCanvas(this.width || 300, this.height || 150);
      }
      this._soft.width = this.width || this._soft.width;
      this._soft.height = this.height || this._soft.height;
      return this._soft.getContext("2d");
    },
    configurable: true,
  });
  Object.defineProperty(proto, "soft", {
    get() {
      void sizes;
      return this._soft ?? null;
    },
    configurable: true,
  });
  return dom;
}
